func (this *Zaif) ParseOrder(order any, optionalArgs ...any) any {
	//
	//     {
	//         "currency_pair": "btc_jpy",
	//         "action": "ask",
	//         "amount": 0.03,
	//         "price": 56000,
	//         "timestamp": 1402021125,
	//         "comment" : "demo"
	//     }
	//
	// cancelOrder
	//
	//    {
	//        "order_id": 184,
	//        "funds": {
	//            "jpy": 15320,
	//            "btc": 1.392,
	//            "mona": 2600,
	//            "kaori": 0.1
	//        }
	//    }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var side any = this.SafeString(order, "action")
	side = Ternary(IsTrue((IsEqual(side, "bid"))), "buy", "sell")
	var timestamp any = this.SafeTimestamp(order, "timestamp")
	var marketId any = this.SafeString(order, "currency_pair")
	var symbol any = this.SafeSymbol(marketId, market, "_")
	var price any = this.SafeString(order, "price")
	var amount any = this.SafeString(order, "amount")
	var id any = this.SafeString2(order, "id", "order_id")
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      nil,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"status":             "open",
		"symbol":             symbol,
		"type":               "limit",
		"timeInForce":        nil,
		"postOnly":           nil,
		"side":               side,
		"price":              price,
		"triggerPrice":       nil,
		"cost":               nil,
		"amount":             amount,
		"filled":             nil,
		"remaining":          nil,
		"trades":             nil,
		"fee":                nil,
		"info":               order,
		"average":            nil,
	}, market)
}

