func (this *Zaif) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	//     {
	//         "id": 23634,
	//         "fee": 0.001,
	//         "txid":,
	//         "funds": {
	//             "jpy": 15320,
	//             "btc": 1.392,
	//             "xem": 100.2,
	//             "mona": 2600
	//         }
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	currency = this.SafeCurrency(nil, currency)
	var fee any = nil
	var feeCost any = this.SafeValue(transaction, "fee")
	if IsTrue(!IsEqual(feeCost, nil)) {
		fee = map[string]any{
			"cost":     feeCost,
			"currency": GetValue(currency, "code"),
		}
	}
	return map[string]any{
		"id":          this.SafeString(transaction, "id"),
		"txid":        this.SafeString(transaction, "txid"),
		"timestamp":   nil,
		"datetime":    nil,
		"network":     nil,
		"addressFrom": nil,
		"address":     nil,
		"addressTo":   nil,
		"amount":      nil,
		"type":        nil,
		"currency":    GetValue(currency, "code"),
		"status":      nil,
		"updated":     nil,
		"tagFrom":     nil,
		"tag":         nil,
		"tagTo":       nil,
		"comment":     nil,
		"internal":    nil,
		"fee":         fee,
		"info":        transaction,
	}
}
func (this *Zaif) CustomNonce() any {
	var num any = this.NumberToString(Divide(this.Milliseconds(), 1000))
	var nonce any = ParseFloat(num)
	return ToFixed(nonce, 8)
}
func (this *Zaif) Sign(path any, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	method := GetArg(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	body := GetArg(optionalArgs, 4, nil)
	_ = body
	var url any = Add(GetValue(GetValue(this.Urls, "api"), "rest"), "/")
	if IsTrue(IsEqual(api, "public")) {
		url = Add(url, Add(Add(Add("api/", this.Version), "/"), this.ImplodeParams(path, params)))
	} else if IsTrue(IsEqual(api, "fapi")) {
		url = Add(url, Add(Add(Add("fapi/", this.Version), "/"), this.ImplodeParams(path, params)))
	} else {
		this.CheckRequiredCredentials()
		if IsTrue(IsEqual(api, "ecapi")) {
			url = Add(url, "ecapi")
		} else if IsTrue(IsEqual(api, "tlapi")) {
			url = Add(url, "tlapi")
		} else {
			url = Add(url, "tapi")
		}
		var nonce any = this.CustomNonce()
		body = this.Urlencode(this.Extend(map[string]any{
			"method": path,
			"nonce":  nonce,
		}, params))
		headers = map[string]any{
			"Content-Type": "application/x-www-form-urlencoded",
			"Key":          this.ApiKey,
			"Sign":         this.Hmac(this.Encode(body), this.Encode(this.Secret), sha512),
		}
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    body,
		"headers": headers,
	}
}
func (this *Zaif) HandleErrors(httpCode any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsTrue(IsEqual(response, nil)) {
		return nil
	}
	//
	//     {"error": "unsupported currency_pair"}
	//
	var feedback any = Add(Add(this.Id, " "), body)
	var error any = this.SafeString(response, "error")
	if IsTrue(!IsEqual(error, nil)) {
		this.ThrowExactlyMatchedException(GetValue(this.Exceptions, "exact"), error, feedback)
		this.ThrowBroadlyMatchedException(GetValue(this.Exceptions, "broad"), error, feedback)
		panic(ExchangeError(feedback))
	}
	var success any = this.SafeBool(response, "success", true)
	if IsTrue(!IsEqual(success, true)) {
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewZaif(userConfig map[string]any) *Zaif {
	p := newZaif()
	p.Init(userConfig)
	return p
}

func (this *Zaif) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe().(map[string]any), this)
	this.exchangeTyped = NewExchangeTyped(&this.Exchange)
}

